'use client';

import { useEffect, useState } from 'react'
import { PMTilesMap } from '@/components/map/PMTilesMap'
import { TemporalControls } from '@/components/controls/TemporalControls'
import { ResolutionControls } from '@/components/controls/ResolutionControls'
import { usePMTilesStore } from '@/stores/pmtiles-store'
import { useTemporalStore } from '@/stores/temporal-store'
import { useResolutionStore } from '@/stores/resolution-store'
import { Layers, Eye, EyeOff } from 'lucide-react'

type DataLayer = 'pfas' | 'total_pesticide' | 'diquat' | 'glyphosate'

export default function Home() {
  const [isInitialized, setIsInitialized] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showBNBO, setShowBNBO] = useState(false)
  const [bnboOpacity, setBnboOpacity] = useState(0.4)
  const [activeDataLayer, setActiveDataLayer] = useState<DataLayer>('pfas')
  const [showLayerSelector, setShowLayerSelector] = useState(false)
  
  // Store hooks
  const { 
    metadata, 
    metadataLoading, 
    metadataError,
    setMetadata, 
    setMetadataLoading, 
    setMetadataError 
  } = usePMTilesStore()
  
  const { setAvailableYears, setCurrentYear, currentYear } = useTemporalStore()
  const { setResolution, currentResolution } = useResolutionStore()
  
  // Load PMTiles metadata on mount
  useEffect(() => {
    async function loadMetadata() {
      try {
        setMetadataLoading(true)
        setError(null)
        
        const response = await fetch('/api/metadata')
        if (!response.ok) {
          throw new Error(`Failed to load metadata: ${response.statusText}`)
        }
        
        const data = await response.json()
        
        // Update stores with metadata
        setMetadata(data)
        setAvailableYears(data.years)
        
        // Set initial year to most recent
        if (data.years.length > 0) {
          const latestYear = Math.max(...data.years)
          setCurrentYear(latestYear)
        }
        
        // Set initial resolution to highest available
        if (data.resolutions.length > 0) {
          const highestRes = Math.max(...data.resolutions)
          setResolution(highestRes)
        }
        
        setIsInitialized(true)
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error'
        setError(errorMessage)
        setMetadataError(errorMessage)
      } finally {
        setMetadataLoading(false)
      }
    }
    
    loadMetadata()
  }, [setMetadata, setMetadataLoading, setMetadataError, setAvailableYears, setCurrentYear, setResolution])
  
  // Loading state
  if (metadataLoading || !isInitialized) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <div className="w-6 h-6 border border-white border-t-transparent rounded-full animate-spin mx-auto mb-3"></div>
          <p className="text-white text-sm font-light">Loading...</p>
        </div>
      </div>
    )
  }
  
  // Error state
  if (error || metadataError) {
    return (
      <div className="min-h-screen bg-black flex items-center justify-center">
        <div className="text-center">
          <div className="text-red-400 text-sm mb-3">
            {error || metadataError}
          </div>
          <button
            onClick={() => window.location.reload()}
            className="px-3 py-1 bg-white text-black text-sm rounded hover:bg-gray-100 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    )
  }
  
  const dataLayerConfig = {
    pfas: {
      name: 'PFAS',
      description: 'PFAS contamination levels',
      colors: [
        { color: 'bg-emerald-400', label: 'Low', range: '< 0.1g' },
        { color: 'bg-blue-400', label: 'Medium', range: '0.1-1g' },
        { color: 'bg-amber-400', label: 'High', range: '1-10g' },
        { color: 'bg-red-500', label: 'Very High', range: '> 10g' }
      ]
    },
    total_pesticide: {
      name: 'Total Pesticide Load',
      description: 'Total pesticide belastning applied',
      colors: [
        { color: 'bg-emerald-400', label: 'Low', range: '< 1kg' },
        { color: 'bg-blue-400', label: 'Medium', range: '1-10kg' },
        { color: 'bg-amber-400', label: 'High', range: '10-100kg' },
        { color: 'bg-red-500', label: 'Very High', range: '> 100kg' }
      ]
    },
    diquat: {
      name: 'Diquat',
      description: 'Diquat active ingredient applied',
      colors: [
        { color: 'bg-emerald-400', label: 'Low', range: '< 100g' },
        { color: 'bg-blue-400', label: 'Medium', range: '100g-1kg' },
        { color: 'bg-amber-400', label: 'High', range: '1-10kg' },
        { color: 'bg-red-500', label: 'Very High', range: '> 10kg' }
      ]
    },
    glyphosate: {
      name: 'Glyphosate',
      description: 'Glyphosate active ingredient applied',
      colors: [
        { color: 'bg-emerald-400', label: 'Low', range: '< 1kg' },
        { color: 'bg-blue-400', label: 'Medium', range: '1-10kg' },
        { color: 'bg-amber-400', label: 'High', range: '10-100kg' },
        { color: 'bg-red-500', label: 'Very High', range: '> 100kg' }
      ]
    }
  }
  
  const currentLayerConfig = dataLayerConfig[activeDataLayer]
  
  return (
    <div className="min-h-screen bg-black text-white relative">
      {/* Minimal Top Bar */}
      <div className="absolute top-0 left-0 right-0 z-50 bg-black/60 backdrop-blur-sm">
        <div className="flex justify-between items-center px-6 py-3">
          <div>
            <h1 className="text-sm font-light">PFAS Environmental Impact</h1>
            <p className="text-xs text-gray-400">Pesticide contamination • Denmark</p>
          </div>
          
          {metadata && (
            <div className="text-right text-xs text-gray-400 font-light">
              <div>{metadata.years.length} years • {metadata.resolutions.length} resolutions</div>
            </div>
          )}
        </div>
      </div>

      {/* Data Layer Selector - Top Left */}
      <div className="absolute top-16 left-6 z-50">
        <div className="bg-black/80 backdrop-blur-sm rounded-lg border border-white/20">
          {/* Layer Toggle Button */}
          <button
            onClick={() => setShowLayerSelector(!showLayerSelector)}
            className="flex items-center space-x-2 px-3 py-2 text-sm hover:bg-white/10 transition-colors rounded-lg"
          >
            <Layers className="w-4 h-4" />
            <span>{currentLayerConfig.name}</span>
          </button>
          
          {/* Layer Selector Dropdown */}
          {showLayerSelector && (
            <div className="absolute top-full left-0 mt-1 bg-black/90 backdrop-blur-sm rounded-lg border border-white/20 min-w-48">
              <div className="p-2 space-y-1">
                {Object.entries(dataLayerConfig).map(([key, config]) => (
                  <button
                    key={key}
                    onClick={() => {
                      setActiveDataLayer(key as DataLayer)
                      setShowLayerSelector(false)
                    }}
                    className={`w-full text-left px-3 py-2 rounded text-sm transition-colors ${
                      activeDataLayer === key
                        ? 'bg-white/20 text-white'
                        : 'text-gray-300 hover:bg-white/10 hover:text-white'
                    }`}
                  >
                    <div className="font-medium">{config.name}</div>
                    <div className="text-xs opacity-75">{config.description}</div>
                  </button>
                ))}
              </div>
              
              <div className="border-t border-white/20 p-2">
                <button
                  onClick={() => setShowBNBO(!showBNBO)}
                  className="flex items-center space-x-2 w-full text-left px-3 py-2 rounded text-sm text-gray-300 hover:bg-white/10 hover:text-white transition-colors"
                >
                  {showBNBO ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                  <span>BNBO Areas</span>
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Full-screen Map */}
      <div className="w-full h-screen">
        <PMTilesMap 
          className="w-full h-full"
          pmtilesBaseUrl="/api/pmtiles"
          showBNBO={showBNBO}
          bnboOpacity={bnboOpacity}
          onBNBOToggle={setShowBNBO}

        />
      </div>
      
      {/* Integrated Bottom Control Panel */}
      <div className="absolute bottom-0 left-0 right-0 z-50">
        <div className="bg-black/80 backdrop-blur-sm border-t border-white/10">
          <div className="max-w-6xl mx-auto px-6 py-4">
            <div className="flex items-center justify-between">
              
              {/* Left: Current State */}
              <div className="flex items-center space-x-6">
                <div className="text-center">
                  <div className="text-lg font-light">{currentYear}</div>
                  <div className="text-xs text-gray-400">Year</div>
                </div>
                <div className="text-center">
                  <div className="text-lg font-light">H3-{currentResolution}</div>
                  <div className="text-xs text-gray-400">Resolution</div>
                </div>
              </div>
              
              {/* Center: Temporal Controls */}
              <div className="flex-1 max-w-md mx-8">
                <TemporalControls />
              </div>
              
              {/* Right: Legend + Resolution */}
              <div className="flex items-center space-x-6">
                <ResolutionControls />
                
                {/* Dynamic Legend */}
                <div className="flex items-center space-x-3 text-xs">
                  {currentLayerConfig.colors.map((item, index) => (
                    <div key={index} className="flex items-center space-x-1">
                      <div className={`w-2 h-2 ${item.color} rounded-full`}></div>
                      <span className="text-gray-400">{item.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
} 